"""Matrix Chain Multiplication — interval DP over the split point.

dp[i][j] is the cheapest way to multiply matrices i..j; the last multiplication
happens at some k, costing dims[i-1] * dims[k] * dims[j].

Time: O(n^3)   Space: O(n^2)
"""
from typing import List


class Solution:
    def matrixChainMultiplication(self, dims: List[int]) -> int:
        n = len(dims) - 1                    # number of matrices
        if n <= 1:
            return 0
        dp = [[0] * (n + 1) for _ in range(n + 1)]
        for length in range(2, n + 1):
            for i in range(1, n - length + 2):
                j = i + length - 1
                dp[i][j] = min(dp[i][k] + dp[k + 1][j] + dims[i - 1] * dims[k] * dims[j]
                               for k in range(i, j))
        return dp[1][n]
